-- Secret-free voting for always-open episode polls (EP004 #architecture-poll).
--
-- The browser calls get_open_poll / cast_open_poll_vote with the site's publishable key, and
-- every rule is enforced here, so no server secret or service-role key is needed:
--   * the tables stay closed to anon/authenticated; only these two functions are callable;
--   * poll_private_settings holds a random salt generated by this migration, readable only by
--     the functions below;
--   * a voter is a random per-browser token, stored only as a salted hash (one vote per token);
--   * the network cap (poll_vote_network_limit trigger) uses a salted, day-scoped hash of the
--     caller IP taken from the API gateway's request headers; raw IPs are never stored;
--   * results are returned only to a voter who has voted (or when the hosts reveal them).

create table public.poll_private_settings (
  id boolean primary key default true check (id),
  salt text not null
);
alter table public.poll_private_settings enable row level security;
revoke all on public.poll_private_settings from public, anon, authenticated;
insert into public.poll_private_settings (salt)
values (replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''));

create function public.poll_private_hash(p_value text)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select encode(sha256(convert_to(s.salt || ':' || p_value, 'UTF8')), 'hex')
  from public.poll_private_settings as s;
$$;

-- The caller's network as seen by the API gateway: an IPv4 address, or an IPv6 /64 prefix.
create function public.poll_client_network()
returns text
language plpgsql
stable
set search_path = ''
as $$
declare
  headers jsonb := nullif(current_setting('request.headers', true), '')::jsonb;
  address text;
  ip inet;
begin
  address := lower(trim(coalesce(
    headers ->> 'cf-connecting-ip',
    headers ->> 'x-real-ip',
    split_part(headers ->> 'x-forwarded-for', ',', 1)
  )));
  if address is null or address = '' then
    return null;
  end if;
  if address ~ '(\d{1,3}\.){3}\d{1,3}$' then
    return substring(address from '((?:\d{1,3}\.){3}\d{1,3})$');
  end if;
  begin
    ip := address::inet;
  exception when others then
    return null;
  end;
  return network(set_masklen(ip, 64))::text;
end;
$$;

create function public.get_open_poll(p_slug text, p_voter text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_poll public.polls;
  v_vote text;
  v_counts jsonb;
begin
  select * into v_poll from public.polls as p where p.slug = p_slug and p.status <> 'draft';
  if not found then
    return jsonb_build_object('poll', null);
  end if;
  if p_voter ~ '^[A-Za-z0-9-]{16,100}$' then
    select v.option_id into v_vote
    from public.poll_votes as v
    where v.poll_id = v_poll.id
      and v.participant_hash = public.poll_private_hash('voter:' || p_voter);
  end if;
  if (v_poll.status = 'open' and v_vote is not null) or v_poll.results_revealed then
    select coalesce(jsonb_agg(jsonb_build_object('optionId', c.option_id, 'count', c.vote_count)), '[]'::jsonb)
    into v_counts
    from public.poll_result_counts(v_poll.id) as c;
  end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'poll', jsonb_build_object('slug', v_poll.slug, 'status', v_poll.status),
    'myVote', v_vote,
    'counts', v_counts
  ));
end;
$$;

create function public.cast_open_poll_vote(p_slug text, p_option text, p_voter text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_poll public.polls;
  v_participant text;
  v_network text;
  v_existing text;
begin
  if p_voter is null or p_voter !~ '^[A-Za-z0-9-]{16,100}$' then
    raise exception using errcode = 'P0001', message = 'poll_invalid_voter';
  end if;
  select * into v_poll from public.polls as p where p.slug = p_slug and p.status = 'open';
  if not found then
    raise exception using errcode = 'P0001', message = 'poll_not_open';
  end if;
  if not exists (
    select 1 from jsonb_array_elements(v_poll.options) as o where o ->> 'id' = p_option
  ) then
    raise exception using errcode = 'P0001', message = 'poll_invalid_option';
  end if;

  v_participant := public.poll_private_hash('voter:' || p_voter);
  select v.option_id into v_existing
  from public.poll_votes as v
  where v.poll_id = v_poll.id and v.participant_hash = v_participant;

  if v_existing is null then
    v_network := public.poll_client_network();
    insert into public.poll_votes (poll_id, participant_hash, option_id, network_hash)
    values (
      v_poll.id,
      v_participant,
      p_option,
      case
        when v_network is null then null
        else public.poll_private_hash(
          'network:' || to_char(now() at time zone 'utc', 'YYYY-MM-DD') || ':' || v_network
        )
      end
    )
    on conflict (poll_id, participant_hash) do nothing;
  end if;

  return public.get_open_poll(p_slug, p_voter)
    || jsonb_build_object(case when v_existing is null then 'voted' else 'alreadyVoted' end, true);
end;
$$;

revoke all on function public.poll_private_hash(text) from public, anon, authenticated;
revoke all on function public.poll_client_network() from public, anon, authenticated;
revoke all on function public.get_open_poll(text, text) from public;
revoke all on function public.cast_open_poll_vote(text, text, text) from public;
grant execute on function public.get_open_poll(text, text) to anon, authenticated, service_role;
grant execute on function public.cast_open_poll_vote(text, text, text)
  to anon, authenticated, service_role;
